    <script>
      (function () {
        var UUID_V4 =
          /^[0-9a-f]{8}-[0-9a-f]{4}-[4][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
        var fromQuery = new URLSearchParams(window.location.search).get('id');
        var parts = window.location.pathname.split('/').filter(Boolean);
        var fromPath =
          window.location.pathname.indexOf('/process/') === 0
            ? parts[parts.length - 1]
            : '';

        if (!UUID_V4.test(fromQuery || '') && !UUID_V4.test(fromPath || '')) {
          return;
        }

        var origin;
        try {
          origin = new URL('https://api.cadastro.uat.unico.app/api/v1').origin;
        } catch (error) {
          return;
        }

        var existing = document.head.querySelectorAll(
          'link[rel~="preconnect"]:not([crossorigin])'
        );
        for (var i = 0; i < existing.length; i++) {
          if ((existing[i].href + '/').indexOf(origin + '/') === 0) {
            return;
          }
        }

        var hint = document.createElement('link');
        hint.rel = 'preconnect';
        hint.href = origin;
        document.head.appendChild(hint);
      })();
    </script>
