    <script>
      (function () {
        var SDKS_BOOTING_FAILSAFE_MS = 20000;

        var isImmersive =
          new URLSearchParams(window.location.search).get('immersive') ===
          'true';
        var pathname = window.location.pathname.toLowerCase();
        var isImmersivePath =
          pathname === '/sdk-s' ||
          pathname.indexOf('/sdk-s/') === 0 ||
          pathname === '/flow' ||
          pathname.indexOf('/flow/') === 0;

        if (isImmersive && isImmersivePath) {
          document.documentElement.classList.add('sdks-mode', 'sdks-booting');

          setTimeout(function () {
            if (
              !document.documentElement.classList.contains('sdks-booting')
            ) {
              return;
            }

            if (
              document.documentElement.classList.contains('sdks-pinned') &&
              typeof Sentry !== 'undefined' &&
              Sentry.captureMessage
            ) {
              Sentry.captureMessage(
                'SDK-S sdks-booting failsafe fired on the pinned path',
                { level: 'warning', tags: { pathname: pathname } }
              );
            }
            document.documentElement.classList.remove('sdks-booting');
          }, SDKS_BOOTING_FAILSAFE_MS);
        }
      })();
    </script>
    <style>
      html {
        height: -webkit-fill-available;
      }
      .spinner {
        box-sizing: border-box;
        border: 4px solid #bdbdbd;
        border-top: 4px solid transparent;
        border-radius: 50%;
        width: 32px;
        height: 32px;
        animation: spin 1s linear infinite;
      }

      @keyframes spin {
        0% {
          transform: rotate(0deg);
        }
        100% {
          transform: rotate(360deg);
        }
      }

      #unico-global-loader {
        background-color: #ffffff;
        display: flex;
        justify-content: center;
        align-items: center;
        height: 100vh;
        width: 100vw;
        position: fixed;
        top: 0;
        left: 0;
        opacity: 0;
        pointer-events: none;
        transition: 0.2s opacity ease;
        z-index: 9999;
      }

      #unico-global-loader.--is-visible {
        opacity: 100;
        pointer-events: all;
      }

      #unico-global-error {
        background-color: rgb(245, 245, 245);
        display: flex;
        flex-direction: column;
        justify-content: center;
        align-items: center;
        height: 100vh;
        width: 100vw;
        padding: 1em;
        position: fixed;
        top: 0;
        left: 0;
        opacity: 0;
        pointer-events: none;
        text-align: center;
        transition: 0.2s opacity ease;
        z-index: 9999;
      }

      #unico-global-error.--is-visible {
        opacity: 100;
        pointer-events: all;
      }

      .error-heading {
        font-size: 1.5rem;
        font-weight: 400;
        line-height: 2rem;
        margin: 1rem 0 0 0;
        color: #333;
      }

      .error-paragraph {
        color: #4f4f4f;
        font-size: 0.875rem;
        line-height: 1.25rem;
        margin-top: 1rem;
        margin-bottom: 2rem;
      }

      .reload-button {
        background-color: #161616;
        color: white;
        border: none;
        height: 40px;
        padding: 0 3rem;
        font-family: 'Atkinson Hyperlegible', sans-serif;
        font-size: 1rem;
        font-weight: 700;
        line-height: 1.5;
        border-radius: 8px;
        cursor: pointer;
        transition: background-color 0.2s ease;
        outline: none;
      }

      .reload-button:hover {
        background-color: #2e2e2e;
      }

      body {
        background-color: rgb(245, 245, 245);
        font-family: 'Atkinson Hyperlegible', sans-serif;
        font-style: normal;
        font-weight: 400;
        margin: 0;
      }

      body.dynamic-wrapper-enabled,
      #root.dynamic-wrapper-enabled {
        background-color: transparent;
      }

      html.sdks-mode body,
      html.sdks-mode #root {
        background-color: transparent;
      }

      #unico-sdks-overlay {
        display: none;
      }

      html.sdks-mode.sdks-ready #unico-sdks-overlay {
        display: block;
        position: fixed;
        top: 0;
        left: 0;
        width: 100%;
        height: 100%;
        background-color: rgba(0, 0, 0, 0.5);
        z-index: -1;
        opacity: 1;
        transition: 250ms opacity ease;
        animation: unico-overlay-fade-in 250ms ease;
      }

      @keyframes unico-overlay-fade-in {
        from {
          opacity: 0;
        }
        to {
          opacity: 1;
        }
      }

      html.sdks-mode.sdks-closing #unico-sdks-overlay {
        opacity: 0;
      }

      html.sdks-mode.sdks-opaque body {
        background-color: rgb(245, 245, 245);
      }

      html.sdks-mode.sdks-opaque #unico-sdks-overlay {
        opacity: 0;
      }

      html.sdks-mode.sdks-opaque #unico-global-loader {
        display: none;
      }

      html.sdks-mode #unico-global-loader {
        background-color: transparent;
        transition: 250ms opacity ease;
      }

      html.sdks-mode.sdks-booting #unico-global-loader {
        display: none;
      }

      html.sdks-mode.sdks-booting.sdks-pinned #root {
        visibility: hidden;
      }

      html.sdks-mode #unico-global-loader .spinner {
        width: 30px;
        height: 30px;
        border: none;
        background: url('data:image/png;base64,') center / contain no-repeat;
        animation-duration: 1.2s;
      }

      .container {
        align-items: center;
        box-sizing: border-box;
        display: flex;
        flex-direction: column;
        min-height: 100vh;
        justify-content: center;
        padding: 1rem;
        text-align: center;
      }

      .heading {
        font-size: 1.5rem;
        font-weight: 400;
        line-height: 2rem;
        margin: 0;
      }

      .paragraph {
        color: #4f4f4f;
        font-size: 0.875rem;
        line-height: 1.25rem;
        margin-top: 1rem;
        margin-bottom: 0;
        margin-left: 0;
        margin-right: 0;
      }
    </style>
